ALTER TABLE creative_projects DROP CONSTRAINT creative_projects_state_check;
ALTER TABLE creative_projects ADD CONSTRAINT creative_projects_state_check
  CHECK (state IN ('DRAFT', 'CONCEPT_GENERATING', 'CONCEPT_REVIEW', 'CONCEPT_APPROVED', 'SCENES_GENERATING', 'SCENES_REVIEW', 'SCENES_APPROVED', 'VOICE_REVIEW', 'VOICE_GENERATING', 'READY_FOR_RENDER', 'COMPOSITION_PENDING', 'RENDERING', 'FINAL_REVIEW', 'SAVING', 'READY', 'FAILED'));
